// Verifies the MATTR AI bridge request WITHOUT throwing, so every request gets a clear HTTP answer.
// Needs on the n8n container: NODE_FUNCTION_ALLOW_BUILTIN=crypto,zlib and the secret in
// MATTR_BRIDGE_SECRET (with N8N_BLOCK_ENV_ACCESS_IN_NODE=false), the same value as the
// backend's TC_N8N_WEBHOOK_SECRET.
const crypto = require('crypto');
const zlib = require('zlib');

const item = $input.first();
const headers = item.json.headers ?? {};
const fail = (status, error) => [{ json: { valid: false, http_status: status, error } }];
// Only these headers reach the database (never the signature itself).
const keep = ['x-idempotency-key', 'x-application-id', 'x-batch-seq', 'x-kind', 'x-part', 'x-of', 'x-timestamp'];
const headersJson = JSON.stringify(Object.fromEntries(keep.filter(k => headers[k] != null).map(k => [k, String(headers[k])])));
const reject = () => [{ json: { valid: true, sig_ok: false, headers_json: headersJson, body_json: '{}' } }];

const secret = $env.MATTR_BRIDGE_SECRET;
if (!secret) return fail(503, 'bridge_not_configured');

let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return fail(400, 'raw_body_missing');
}
if (!raw || raw.length === 0) return fail(400, 'empty_body');
if (raw.length > 6 * 1024 * 1024) return fail(413, 'part_too_large');

const ts = String(headers['x-timestamp'] ?? '');
const sig = String(headers['x-signature'] ?? '');
if (!/^\d{9,11}$/.test(ts) || !sig.startsWith('sha256=')) return reject();
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject();   // older than 5 minutes: replay

const expected = 'sha256=' + crypto.createHmac('sha256', secret)
  .update(Buffer.concat([Buffer.from(ts + '.'), raw])).digest('hex');
const a = Buffer.from(expected), b = Buffer.from(sig);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject();

let body;
try {
  body = zlib.gunzipSync(raw, { maxOutputLength: 64 * 1024 * 1024 }).toString('utf8');
  JSON.parse(body);
} catch (e) {
  return fail(400, 'not_gzipped_json');
}
return [{ json: { valid: true, sig_ok: true, headers_json: headersJson, body_json: body } }];
